    Bug 1817769 - Add more info output to better understand test timeouts of browser_timezones.js. r=arschmitz

    This test fail is difficult to reproduce. Adding some more info output
    to better understand where the timeout happens (it seems to always
    happen in `add_setup()`.

    Differential Revision: https://phabricator.services.mozilla.com/D228440

diff --git a/calendar/test/browser/timezones/browser_timezones.js b/calendar/test/browser/timezones/browser_timezones.js
index 41279bab84f..c31b3a4de4f 100644
--- a/calendar/test/browser/timezones/browser_timezones.js
+++ b/calendar/test/browser/timezones/browser_timezones.js
@@ -51,7 +51,9 @@ add_setup(async () => {
     CalendarTestUtils.removeCalendar(calendar);
   });

+  info("Initializing <day> view.");
   await CalendarTestUtils.setCalendarView(window, "day");
+  info("Switching to 1/1/2009.");
   await CalendarTestUtils.goToDate(window, 2009, 1, 1);

   // Create weekly recurring events in all TIMEZONES.
@@ -68,11 +70,12 @@ add_setup(async () => {
   const time = cal.createDateTime();
   for (let i = 0; i < TIMEZONES.length; i++) {
     const eventBox = CalendarTestUtils.dayView.getHourBoxAt(window, i + 11);
+    info(`Checking content of hour box for <${TIMEZONES[i]}>.`);
     const { dialogWindow, iframeWindow } = await CalendarTestUtils.editNewEvent(window, eventBox);
     time.hour = times[i][0];
     time.minute = times[i][1];

-    // Set event data.
+    info(`Setting event data for <${TIMEZONES[i]}>.`);
     await setData(dialogWindow, iframeWindow, {
       title: TIMEZONES[i],
       repeat: "weekly",
@@ -81,8 +84,10 @@ add_setup(async () => {
       timezone: TIMEZONES[i],
     });

+    info(`Saving event data for <${TIMEZONES[i]}> and closing item dialog.`);
     await saveAndCloseItemDialog(dialogWindow);
   }
+  info(`Completed setup for timezone test.`);
 });

